WITH valid AS (SELECT id, order_id, method, amount, paid_at, status, DATE_TRUNC('WEEK', paid_at) paid_at_period, COALESCE(method, 'DIRECT') method_clean FROM payments WHERE paid_at >= TIMESTAMP '2024-01-18 22:00:00'), flagged AS (SELECT *, CASE WHEN LAG(paid_at_period) OVER (PARTITION BY method ORDER BY paid_at_period, id) IS NULL OR paid_at_period > LAG(paid_at_period) OVER (PARTITION BY method ORDER BY paid_at_period, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM valid), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, method, ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) AS session_start_flag_per_success, COUNT_IF(status = 'REFUNDED') AS refunded_events, ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN method = 'bank_transfer' THEN 1 END), 0), 2) AS session_start_flag_per_bank_transfer, COUNT(*) FILTER (WHERE method = 'paypal') AS paypal_rows, MAX(session_start_flag) FILTER (WHERE method = 'promptpay') AS promptpay_max_session_start_flag, COUNT(DISTINCT order_id) AS distinct_order_ids, GROUPING_ID() AS gid FROM islands GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', paid_at), method), (DATE_TRUNC('WEEK', paid_at))) HAVING ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) > 0;
